  "subcat": "标记基因辅助的主题模型",
  "innov": "用标记基因辅助的主题模型做解卷积，同时估计每个 spot 的细胞类型比例与基因表达谱。",
  "sig": "把标记基因的先验和主题模型结合，在没有高质量单细胞参考时也能给出稳定的组成估计。",
  "link": "https://doi.org/10.1186/s13059-024-03441-1",
