  "tool": "KLFDAPC",
  "name": "KLFDAPC",
  "first": "",
  "corr": "Xinghu Qin & Oscar E Gaggiotti",
  "cat": "统计遗传学与空间统计",
  "subcat": "spatial genetic structure analysis",
